BEGIN;

SET LOCAL search_path = public;

ALTER TABLE public.professor_review ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.professor_review_course ENABLE ROW LEVEL SECURITY;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (477::BIGINT, 'De las mejores profes, en mi caso de mate general, se le entiende muy bien y siemore está pendiente de aclarar todas las dudas, además constantemente nos motiva a dar lo mejor de nosotros y hace que formemos un enlace en clase, de lo mejor para mi es que hace que las clases sean divertidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4ae728d2c7406f8b4dd5754bac682d1d841169f4b6a9de2e442594a34268021a'::TEXT, ARRAY[563, 605]::BIGINT[]),
    (477::BIGINT, 'Es la mejor profe. Muy chistosaa, no hay clase aburrida. Te hace entender de manera divertida la mate, siempre está dispuesta a ayudar y da muchas palabras de motivación, es muy comprensiva... Es de verdad, una profe Excelente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-04-01T00:00:00+00:00'::TIMESTAMPTZ, 'd421e556c922fcc27825001fdafb704db52c467f3dbaec4ab600e6f54552fcdd'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'La mejor profe con la que he llevado CDI (lo he llevado 4 veces), enseña como si uno estuviera en la escuela y la verdad eso ayuda mucho a dejar las dudas claras. Da MUCHOS tips para aprender fórmulas, procedimientos atajos en los ejercicios. Califica un poco rudo, pero con práctica CONSTANTEselogra'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-03-11T00:00:00+00:00'::TIMESTAMPTZ, '13d009d9e5414f351fe7af44e0dc2912a2fc42ca10a361d12599651c7b135899'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Una excelente profesora, no va a encontrar ningún profesor de matemática como ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '8b150bedcfbfb412fa6bf578c6b3fb5006860a386330b5196e2fd35ebfbf1a8c'::TEXT, ARRAY[1018]::BIGINT[]),
    (477::BIGINT, 'te amo Ivonne'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'b97af932cb029ed739b5f25bb97c923c5cc1fecbcbd25848af77287497617283'::TEXT, ARRAY[1018]::BIGINT[]),
    (477::BIGINT, 'La verdad considero que hace bastante llevadero un curso tan diificil y es muy amable y comprensiva.No califica tan duro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '758b4b6f465c61830f71d0d1627ab9d1ff8902787f2de47056f0f285c3d14d7e'::TEXT, ARRAY[1018]::BIGINT[]),
    (477::BIGINT, 'Es fácil de las mejores de la cátedra. Explica súper claro y es muy chistosa entonces la clase nunca es aburrida. Para calificar es bastante buena porque incluso si usted tiene algún ejercicio mal, le rescata cosas que están bien para no ponerle 0. Deja trabajos extra que ayudan mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Da crédito extra']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '13e2554b68f770544a1525062e579b9a65097db2498df52f9b5a4e27980536df'::TEXT, ARRAY[1018]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-03-17T00:00:00+00:00'::TIMESTAMPTZ, '924561049b7c452235b21ed123992c3b5ba0660ca8bab0f79ca2f944eb8a379c'::TEXT, ARRAY[1018]::BIGINT[]),
    (477::BIGINT, 'Explica de una manera que hace que el curso no sea tan pesado Deja tareas opcionales para sumar puntos a la nota'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '86b17243053eacc013b0e70ba91df63db630a823e276cc030ae1ffecdd95ad76'::TEXT, ARRAY[1018]::BIGINT[]),
    (477::BIGINT, 'De las mejores profes, explica excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, '830fbca504be11b104ac9befb95ccf7e4f5f307612d0df8d54a97d3c8deab275'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Simplemente la mejor profe de mate. Se preocupa porque todos los estudiantes entiendan la materia explicando de una manera en la que es fácil entender y sin importar si debe de explicar varias veces. También se preocupa por el bienestar de sus estudiantes y los motiva a continuar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e61b107921d47cb0290d8121091b28fcf67086162bf19475fc907573b83d5c7d'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Es divertida, optimista y amigable. Sus clases son claras, explica de diferentes maneras, si usted necesita que le expliquen más de una vez ella lo hará con gusto, lo prepara bien a uno para los exámenes y sus tareas son super fáciles si se pone atención en clases. Uno termina queriéndola en serio!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '541138ace66cf90ec61c30ba97179b729da37c62b79cd36d97debe0efe5b78cb'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Simplemente la mejor profe de mate, si tiene la oportunidad de matricular con ella hágalo, explica super claro y de una manera que todos entiendan además trata de que pasemos un buen rato en la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '7ffb7971b268687f0659600c939f69c35710022235c83c65fe86815c37cbdc33'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente profesora, no duden matricular un curso con ella. Hace la clase súper amena y siempre está anuente a explicar las veces que sean necesarias para que uno entienda, dentro y fuera de la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-17T00:00:00+00:00'::TIMESTAMPTZ, '686a755c19ddf56fcb4013e6530fb51e0ccce36567df96448e62673b9a620aff'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente profe y personas, explica todos los temas de una manera muy clara y los portafolios son de gran ayuda. Cualquier curso con ella es un exito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '342c6ee65378e98de23e0ea372f64f97619b45ee93033b01864351af2b3058bb'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'La profe Ivonne es un amor y ayuda demasiado. No dude en matricular con ella. Es muy organizada y las clases no se hacen pesadas siempre y cuando usted ponga atención y participe en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'd5bbde58cf0770a4218413b6b5931062172c651ed53c625cc22634c4e7a77c19'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Si tiene la oportunidad de matrícular con ella no la deje ir!!! Llevaría con ella otro curso sin dudarlo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'df9f3df1544d265f2f10deafc198925390167420ea4c610b6809cdecf5b71fd2'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Las clases son largas pero valen la pena, siempre está para uno… explica súper bien, es de lo mejor que tiene el TEC como profesora.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'c56581186658af27fe0428ad86187d50c75ef28ca861b18450ed534cc411d449'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'La profesora es un amor de persona, siempre se preocupa por el bienestar de los estudiantes. Explica muy bien los temas y si no se entiende, se devuelve para aclarar la materia. Las clases son largas y se vuelven tediosas, también deja portafolios semanales y varias tareas pero ayudan para entender'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '48feddc85aa1c5e2a60c2be71b5749d67469d2e541d82548231d765b0f4898ca'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Es muy buena profe y explica muy bien con detalle, solo que eso hace que las clases se vuelvan un toque largas y tediosas. Manda mucho trabajillos o portafolios semanales que requieren tiempo, pero ayudan a practicar. Es un amor de persona, se preocupa por la salud mental de sus estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '847e268745e364979ad734f0854c6e7f63c4371e14287ab11acb6c551efbc222'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Buena profe, solo que los ejercicios que hace son mas fáciles que los de la catedra, ella en general es super linda y super pura vida. Pero se atrasa mucho con las evaluaciones y no las lleva al dia. Brinda unos folletos super buenos para entender la materia.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5ff5b8ae61b9c22aff5de12516b7a88bd20bf7405d7122414b8a9f7b31ab4a5b'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'La profe es buena explicando y está muy atenta a resolver dudas. Le gusta mucho la participación en clase'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases largas']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '1510b2c36fa522e941b5f06b3bc9026080e0948c62da5e058e64cc375ba9d962'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'La profe es buena, pero, personalmente, considero que es buena de manera presencial, virtualmente veo mucho mejor a otros profesores.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '33558061992b15dfb19836951dc5146fc8117635f43f78aba58947176191161e'::TEXT, ARRAY[1034]::BIGINT[]),
    (477::BIGINT, 'La profe es excepcional. Explica super claro. Con ella se aprende un montón. Te prepara genial para los exámenes. Resuelve todas las dudas. Ella es super amable y divertida.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '2e2bd54e998ad244b9617cf85f9992744ea23855ba4e0fbf0797417cac8be40d'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'La profe es todo un amor, le explica hasta que usted entienda y si ocupa ayuda con las prácticas se la da, sean buenos con ella y participen o prendan la cámara :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'dfcdffd221dfb6f9237c3097003fa0227e1c412ff9819660696d0ccfab33966d'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Es posiblemente la mejor profe de mate que he tenido, explica muy bien y le ensena a uno estrategias y trucos de mate que son no convencionales pero sirven muy bien. Además los quices y tareas que deja son muy fáciles y sirven para subir la nota'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '1c78b26891696b830daa5512c4002ccc3c43e408dcb2b85eb08db112df38f61a'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Ayuda bastante, se preocupa por sus estudiantes dejando resúmenes, prácticas y tareas. Aunque las clases en modalidad virtual fueron largas, ella las hace bastantes llevaderas. La participación es importante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '0c2b517d45769d089f88b42f61b63e332dfa16d7ce7a112b08d2cd0fc551556b'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Explica muy claro. Se preocupa por que los estudiantes aprendan. Si puede matricular cualquier curso con ella no lo dude. La mejor profesora que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '60045a07dadaca2a24451b8c6260ef79443064ca2ada95f81ef8aee8f0423b3f'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Excelente se preocupa porque los estudiantes entiendan, deja prácticas que seimpre ayudan para los exámenes, siempre avisa las fechas de quices así como los temas que salen y siempre son temas vistos anteriormente. Uno se rie bastante en clase, las clases son muy llevaderas. No dude en matricular.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'fa85d05d828bf346e5fd6d14d55baaca031a9f18d1e0c367115b823353604337'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Es probablemente una de las mejores profes que tiene el TEC y la escuela de Matemáticas, es un amor de persona, mate general es un curso medio :/ y ella explica muy bien y ayuda bastante! Volvería a llevar con ella'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'f70dcf31964c24593d579fd28a321e2d169cc7b61ccce2b07510c14d2554c43a'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'ES LA MEJOR PROFE CON LA QUE PODRÍA MATRICULAR, ES DEMASIADO BUENA, SE PREOCUPA POR UNO Y EXPLICA SÚPER BIEN.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '383ea7f88f4437fce737da20c806523a6c49839096d631c5420c89cf0d3ab889'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Unas de las mejores profesoras, sino la mejor, que he encontrado en el TEC, no duden en matricular con ella, si usted está volviendo a llevar este curso, Ivonne es la ideal, se preocupa por sus estudiantes, explica muy claro y es demasiado cómica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '8f5ef2907bd6f18798c43ba184542fa3301ebc75c84c775d87e379c51c62f9a3'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'La mejor profesora del curso que he tenido, tuve que repetir el curso y la verdad ella deja todo súper claro y es paciente con uno, explica un millón de veces o con colores si es necesario, es llevadera y sus clases carecen de una seriedad innecesaria que algunos profesores suelen poner'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'a7c787cfda764befaefabebb770664c12687e29ded4df5eb6c60fa9801b6019d'::TEXT, ARRAY[605]::BIGINT[]),
