    (477::BIGINT, 'Es buena gente y explica bien, es como una profesora de colegio. Tiene paciencia y es graciosa, le da buen ambiente a la clase. La recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-15T00:00:00+00:00'::TIMESTAMPTZ, '737f7428d58bb8ecbec488c7cd171a5a82f49357e05652c31ae4c7dfb19b22d3'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'La profe Ivonne es excelente. Explica de forma muy amigable, hace chistes internos para recordar temas que de verdad si sirven, y nunca se enoja si alguien no entiende algo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5c929f224c2b9a290bc36dad9f0aa3e71fd31df7ab5d3d5190d39c18b3de8f50'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Una profe excelente, ama lo que hace y las clases son muy entretenida, a mi siempre me han aburrido las mates y en esa clase la pase super bien y super atento a pesar de eso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8c1313186eae18123e0cfabdbfd8ca2024580b01ae295991d95017966d21bef4'::TEXT, ARRAY[1018]::BIGINT[]),
    (477::BIGINT, 'La profe es muy buena, siempre intenta llevar una buena vibra a la clase y que todos se sientan cómodos, explica ciertas cosas de manera más sencilla para que sea mejor de entender, muy recomendada'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'dd9307a2f000174bc0acc5e33d4bcd969a2f88111a3d6b2feb84c8e6f2e3c2f4'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Simplemente lo mejor que tiene la escuela de mate, demasiado clara, ordenada y preocupada porque el estudiante aprenda, da mucho material que ayuda un montón. Vayan a clases y participen, ella es demasiado buena persona, es lo mínimo que uno puede hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b6ef83b09e3abbe7f132fffb2610f5c96c4f783447dace09c1d0ac5ffe6a2c11'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Buena profe y gran persona, realmente el curso con ella es super ameno, es divertida y explica casi con plasticina. Lo único que no me gusto fue que puso las notas hasta el final final del curso entonces usted no sabe sus notas de semana 1 sino hasta semana 18'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b45b0364ee0592989eeb441f7897439fb97ae8f8f8dcb85fdddd5f42d398c318'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'La profe es excepcional. Explica super claro. Con ella se aprende un montón. Te prepara genial para los exámenes. Resuelve todas las dudas. Ella es super amable y divertida.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'be5f0239d8b43430d46abfbc8547e68fedb5486d9b91df78f07fef7adb1e0eea'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Es la mejor profesora que hay, se preocupa por sus estudiantes, enseña con dedicación y cariño, las clases son súper divertidas, hay que disfrutarlas demasiado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '4d913bc4e716e6d7571a7fbee21d2ac36cacfca4ce22a50dcc2dfcbc84bed524'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'c5d9ce1a54be3901e98cffce800f76c3ea87981054b1a9e5e613f8f10ded26c4'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente profe, explica todo como si enseñara a niños, no importa si se tiene malas bases, ella todo lo explica despacio y con claridad. La mejor profe que me ha tocado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ed47a045966e9c689c8e2e3c9180ffda88d5779b9f56136a9019439434653e14'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'La mejor profe que he tenido en la U, excelente persona y AMA lo que hace, realmente sabe demasiado y le encanta enseñar, tiene demasiada paciencia y explica demasiado bien. Simplemente 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-11T00:00:00+00:00'::TIMESTAMPTZ, '786b92d182c5042f520a8d0713286e5e3b32997a15896d1cf24fadcd555904df'::TEXT, ARRAY[2439]::BIGINT[]),
    (477::BIGINT, 'Si al estudiante le cuesta la mate, le explica con toda la paciencia del mundo. Si no le cuesta, entonces la clase igual es interesante y entretenida. Súper buena profe para explicar cosas complicadas y que cualquiera las entienda!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a34b948f5e836ee40110281b31dc1986ebbdfe9b1591ababde5071cee2548b52'::TEXT, ARRAY[1647]::BIGINT[]),
    (477::BIGINT, 'Es una persona muy carismática y con mucha paciencia, el curso muy entretenido, muchas dinámicas interesantes en clase y bastante participación por parte de los estudiantes. De las mejores profes que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '32149d4a9eac1265b03385dfd487a8ce6dcc0cdc17d3ca49973002901dbac450'::TEXT, ARRAY[1620]::BIGINT[]),
    (477::BIGINT, 'La amo, ella es excelente en todo, sumamente clara y deseosa de ayudar siempre que uno lo necesite.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2018-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'fa8c60491fba38507500b3128a212d8b6e422551570199ad5e87af3232a3659a'::TEXT, ARRAY[2439]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-02-04T00:00:00+00:00'::TIMESTAMPTZ, '02288a120a82f2f1d0561e69393dff1f02c8fa4d8eaf81e75c395d09a865e4b0'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'ES LA MEJOR PROFE DEL MUNDO EN SERIO!!!!!! explica super bien y es paciente con uno y da muchos ejemplos que ayudan demasiado para los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '857aba033c697df65a03d8d55203c5d22f0bda3f18e6aff44b15f450424b0c93'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'ab853cf7eb5c0355965e7ab9b9cb598e073b1533be50b522294229a51c5b3645'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ella es la mejor profe de mate general, si usted tiene la oportunidad de matricular con ella, hágalo sin miedo, ella es demasiado amor para esta vida. Super ayuda si usted no está entendiendo algo, ella de verdad es la mejor profe de mate general.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-16T00:00:00+00:00'::TIMESTAMPTZ, '4f2bc4d93befd81ed16c3dc6fa53a8d26d0d949022b431eceb14bce69e4c17d5'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Es una profe excelente, si tiene la oportunidad de matricular con ella, hágalo. Lo ayuda a uno mucho con la materia, deja muchos quizes y tareas pero se preocupa porque uno entienda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'a53cdf72136cabb68becdba6b567e6617cab624b165c02603a72bb549d0828a2'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente profesora. Se preocupa mucho por el aprendizaje del estudiante. Explica muy claro y da ejemplos muy comprensibles. Es muy divertida y como persona es un amor. La recomiendo al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '2c9f20802a4e9e61854ea51d1fdf16bb236fdc2ea93d5fc21f004bda8a681aae'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Es un amor de persona. Ayuda un montón para que uno entienda. Da ejemplos vacilones, deja muchos quices y tareas pero son fáciles y le ayuda para tener la materia al día, explica las veces que sea necesario y califica justo. Definitivamente una profe que da clases con amor, 100% recomendada!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c79661279e7a248bcbc2929e726085c59ea2865ecee92092eed23a92c75e3827'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Muy buena persona, ayuda muchísimo, explica para todos con muchos ejemplos y de distintas maneras. Hace muchos quices y tareas y eso ayuda para que usted esté al tanto de la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '5f92eab8527d3ba8fb5e8d1bb09d1c49e535ed97fd233bd63295b4fb8ab0ea13'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, '87a3c0ad863f5ea38374e5289dfa11342ef38fdfa0ea52f07974273f8ec158f0'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'c008cace48af8395b504fbbe39934c1226783decf8d6fdc1a838c48a4dbb6d10'::TEXT, ARRAY[2439]::BIGINT[]),
    (477::BIGINT, 'Es sencillamente, excelente. Sus clases son muy amenas y hace bastante quiz, algo que empuja al estudiante a prepararse bien antes del examen. 100% recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-05T00:00:00+00:00'::TIMESTAMPTZ, '70019b89a74ffe636efadcc2cbc25cf50fc844124dd6feb5ea62c34ce7fafbf4'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'La mejor profesora!, explica muy bien y te ayuda. Es súper buena nota!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-04-05T00:00:00+00:00'::TIMESTAMPTZ, '4ed3d8b7e3812737811e542a045d3774285024fdb327bf038d66220f752fd513'::TEXT, ARRAY[563, 605]::BIGINT[]),
