    (477::BIGINT, 'Excelente profesora no tiene que dudar nada, solo matricule con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, '45648c5725fbd004509eedb392a4ff923d27c7cc83ca4788ffcbfbebdc794079'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Super buena profe ,clases con mucho humor ,se aprende bastante ,definitivamente ayuda mucho ,la clase se entiende y ademas se disfruta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'ff355d1b77c74edee2f93598d5c2fd480c5540d75c4d2246c0fc6ca2179187d2'::TEXT, ARRAY[1034]::BIGINT[]),
