    (477::BIGINT, 'Excelente! La mejor, explica demasiado bien y se preocupa por que todos entiendan!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, '92393ee769f6ce4b67dacb129a61d204504e23e00246b733665f74470605892d'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Excelente!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7219cca6902cdf01e1da790667027a20a58d979763cd420bed29592a8ff0c3aa'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, '¡La mejor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-20T00:00:00+00:00'::TIMESTAMPTZ, '1647cd8389443420214cd83a34e50dcf211f90ea94a124f70c5cf0d847615e7e'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Excelente profe, explica demasiado bien, explica las veces que sea necesario y siempre busca que uno salga bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-07T00:00:00+00:00'::TIMESTAMPTZ, '2bf4b919b7a543db484a5d5e85015a58c3a8a78989b8a71cf2eb7666d21956d1'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Se preocupa por que los estudiantes entiendan y aprendan, hace la clase divertida, es un amor y definitivamente es una de las mejores profes que uno pueda llegar a tener. Ud va a aprender con ella sí o sí...10 de 10.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-10-12T00:00:00+00:00'::TIMESTAMPTZ, '2ad8326621f005422e892706fba23a59091cd22b2e98f4b1ad393b35b459e9c8'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Exelente profe. Explica muy claro, atiende dudas y explica las veces que sea necesario. Además hace que la clase tenga un ambiente agradable ya que vacila con los estudiantes y no es para nada ceria jaja. Califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2016-10-12T00:00:00+00:00'::TIMESTAMPTZ, '4188340eceaf0585558a0d13449b7a0aea38e77811790eef99c40894c1c73384'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'La mejor profesora por mucho, hace que las clases sean entretenidas. Sabe un montón y hace que el estudiante entienda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2016-09-05T00:00:00+00:00'::TIMESTAMPTZ, 'c1993ac5e2ae5af704e84bcc6ad13184684de1eb2984f5f241747ea4fb7f68e3'::TEXT, ARRAY[605]::BIGINT[]),
    (477::BIGINT, 'Excelente profesora! Deja todo muy claro y hasta al más idiota ayuda. La recomiendo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b1678020c8a150127ff52e19d5199a534710d3cd8c5c7cc176a00c8705bc818b'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Una excelente profesora, explica súper claro y atiende todas las dudas posibles! Súper recomendada!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '950f647edb491f2b3df7b1423103ec0a4a19dcc02e42978bd1e9d2d53c49f242'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '493f487939d987fcdf746095ecc779d82fb3770bb32b9652b3205668315f25a1'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'El que comento que no explica bien y así esta MAMANDO. La profesora ideal para el curso si usted no sabe todo lo del cole porque lo repasa y se "molesta" con ella, Llevaría cualquier curso con ella Una teja de persona y profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '931355aa757b21b10003a56b7dbd5b3d15bb4696617dd46110f77de77898d3ed'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'No es mala, pero si hay que poner mucho esfuerzo de más porque no basta con lo de ella, no es la mejor profesora, pero es una buena opción si tiene facilidad con la matemática, si le cuesta un poco ni lo piense...'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '8361bb5feef46d2ac88f7c697865e6cbfebb07b7e63000a78a52615deda37691'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente Profesora, sus clases son muy dinámicas y se preocupa por que el estudiante aprenda, deja tareas lo cual ayuda en la calificación, y la manera de enseñar es muy "pegajosa" lo cual permite recordar con facilidad la materia vista en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '91a3a88fed22956563de5ce997ae61129dd58002c756f4c52bab6e4f2e415974'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente profe y persona. Explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '05fe8fbdb969af9169246607613aebcae8dbf0bcb21a9ca8f7b745fde533f87d'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Explica con claridad la materia, se detiene ante alguna duda y suele usar términos más coloquiales para que los estudiantes entiendan mejor el tema. Fomenta un ambiente de confianza y "Basile" entre ella y los estudiantes sin dejar de lado la clase Exelente profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '39a6ea6835cf150ad59054498fac0b0a5158102efdf1ffd9dd95374a0c2b084f'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'muy buena profesora muy responsable y excelentes clases'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c583e33c1285b099988a453e9fe5a70297655077bebb603bf6f0309751fac840'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ff439a40cf6188f384d1d1c374d906fea82c58ba5686cd917c09ff0c8373854f'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ccf0db62e5c8bd25a88ac3be1f798c37a8b6dd9f8f924d6de62731a7bb6c9499'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'c3b6590460ae2bdf60ddda9e7e6a677083ef4920c65a910a911800ce442d257b'::TEXT, ARRAY[563]::BIGINT[]),
    (477::BIGINT, 'Excelente profesora, es muy buena, responsable y explica de la manera más sencilla para entender los temas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '4e4e3660e21106becaeecbdd8b99868b8c0dfba4d765106ee20e0dd542dd3dd3'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
